-- k8s 세트 339. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 원본: 02_quest_set.sql, 03_quest_set339.sql. 단원·display_order·아이콘은 통합 시 별도로 정한다. docs/specs/spec_k8s_pod_diagnosis_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 339, '깨진 Pod 진단 실습: ImagePullBackOff·CrashLoopBackOff·OOMKilled·readiness 실패 읽고 고치기', 'describe 의 Events 와 Last State, logs --previous, logs -c, get events --sort-by, exec 로 깨진 Pod 의 원인을 읽고, 잘못된 이미지 태그(set image)·잘못된 명령(다시 만들기)·너무 작은 메모리 한도(OOMKilled, 137)·실패하는 readinessProbe(READY 0/1)를 고치는 과정을 클러스터 상태와 저장한 파일 내용으로 확인하며 익힙니다.', 'k8s', 'k8s'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 339);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 1, 'describe 로 ImagePullBackOff 원인 읽기', 'Pod `diag-img` 가 시작되지 않고 있습니다. `kubectl get pods` 를 보면 STATUS 가 `ErrImagePull` 또는 `ImagePullBackOff` 입니다. **`describe` 로 자세히 본 결과를 `/tmp/describe.txt` 에 저장**하고, 맨 아래 Events 에 이미지를 못 받았다는 이유가 적혀 있는지 읽어 보세요.', '`kubectl describe pod 이름` 의 출력은 `>` 로 파일에 저장할 수 있어요. 원인은 맨 아래 Events 표에 있어요.', 'kubectl describe pod diag-img -n $NS > /tmp/describe.txt
cat /tmp/describe.txt | tail -15

# Events 에 Failed to pull image "busybox:1.99" 같은 줄이 보인다 (그런 태그는 없다는 뜻)
# 이미지 문제는 컨테이너가 한 번도 시작하지 못해서 logs 가 비어 있다. describe 의 Events 가 단서다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-img\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.99\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n\\nEOF\\ni=0; while [ $i -lt 90 ]; do if kubectl get pod diag-img -n $NS -o jsonpath=''{.status.containerStatuses[0].state.waiting.reason}'' 2>/dev/null | grep -Eq ''ErrImagePull|ImagePullBackOff''; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]', '["sh", "-c", "( grep -Eq ''^Name: +diag-img$'' /tmp/describe.txt ) && ( grep -q ''^Events:'' /tmp/describe.txt ) && ( grep -Eq ''Failed to pull image|Back-off pulling image'' /tmp/describe.txt ) && ( kubectl get pod diag-img -n $NS >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일이 Pod diag-img 의 describe 이다", "cmd": ["sh", "-c", "grep -Eq ''^Name: +diag-img$'' /tmp/describe.txt"]}, {"label": "Events 구역이 들어 있다", "cmd": ["sh", "-c", "grep -q ''^Events:'' /tmp/describe.txt"]}, {"label": "이미지를 못 받았다는 이벤트가 보인다", "cmd": ["sh", "-c", "grep -Eq ''Failed to pull image|Back-off pulling image'' /tmp/describe.txt"]}, {"label": "Pod 는 지우지 않았다", "cmd": ["sh", "-c", "kubectl get pod diag-img -n $NS >/dev/null 2>&1"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 2, 'kubectl set image 로 틀린 이미지 태그 고치기', 'Pod `diag-img` 의 이미지가 `busybox:1.99` 로 잘못 적혀 있어 시작하지 못합니다. **이미지를 `busybox:1.36` 으로 고쳐** Pod 가 Ready 가 되게 하세요. (컨테이너 이름은 `main` 입니다. 지우고 다시 만들어도 됩니다.)', '`kubectl set image pod/이름 컨테이너이름=이미지:태그` 형식이에요. 컨테이너 이름은 `describe` 의 Containers 아래에 나와요.', 'kubectl set image pod/diag-img main=busybox:1.36 -n $NS
kubectl get pod diag-img -n $NS -w   # Running, 1/1 이 되면 Ctrl+C

# Pod 의 이미지는 실행 중에도 바꿀 수 있는 몇 안 되는 필드다
# 바뀐 이미지로 컨테이너가 새로 시작된다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-img\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.99\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n\\nEOF\\ni=0; while [ $i -lt 90 ]; do if kubectl get pod diag-img -n $NS -o jsonpath=''{.status.containerStatuses[0].state.waiting.reason}'' 2>/dev/null | grep -Eq ''ErrImagePull|ImagePullBackOff''; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]', '["sh", "-c", "( [ \\"$(kubectl get pod diag-img -n $NS -o jsonpath=''{.spec.containers[0].image}'' 2>/dev/null)\\" = \\"busybox:1.36\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get pod diag-img -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = true ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( [ \\"$(kubectl get pod diag-img -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Running\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "컨테이너 이미지가 busybox:1.36 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod diag-img -n $NS -o jsonpath=''{.spec.containers[0].image}'' 2>/dev/null)\\" = \\"busybox:1.36\\" ]"]}, {"label": "컨테이너가 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get pod diag-img -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = true ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "Pod 가 Running 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod diag-img -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Running\\" ]"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 3, 'get events 를 시간순으로 정렬하기', '장애 때는 이벤트를 **오래된 것부터 최근 것 순서**로 읽으면 흐름이 보입니다. 이벤트가 시간 순서대로 나오도록 빈칸에 알맞은 정렬 필드를 고르세요.', '`--sort-by` 에는 오브젝트 안의 필드 경로(점으로 시작)를 줘요. 이벤트에는 "마지막으로 일어난 시각" 필드가 있어요.', NULL, NULL, '[]', 'fill', '[".lastTimestamp", ".time", ".timestamp", ".metadata.time"]', NULL, '`kubectl get events` 는 기본으로 시간순이 아닙니다. `--sort-by=.lastTimestamp` 를 주면 마지막 발생 시각 기준으로 오래된 것이 위, 최근 것이 맨 아래에 놓여 방금 일어난 일을 읽기 편합니다. `.time`, `.timestamp`, `.metadata.time` 은 이벤트에 없는 필드라 쓸 수 없어요.', '[0]', 'kubectl get events --sort-by={0}', NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 4, 'logs --previous 로 직전 컨테이너 로그 읽기', 'Pod `diag-crash` 는 시작하자마자 종료되기를 반복(CrashLoopBackOff)합니다. 방금 죽은 **직전 컨테이너가 남긴 로그**를 `/tmp/prev.log` 에 저장하고, 죽기 직전에 무슨 말을 했는지 읽어 보세요.', '컨테이너가 이미 다시 시작된 뒤라서, 지금 컨테이너가 아니라 "이전" 컨테이너의 로그를 보는 옵션이 `kubectl logs` 에 있어요.', 'kubectl logs diag-crash -n $NS --previous > /tmp/prev.log
cat /tmp/prev.log

# boom: config file not found 처럼 죽기 직전의 마지막 말이 보인다
# 재시작 직후엔 새 컨테이너 로그가 비어 있을 수 있어 --previous 가 중요하다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-crash\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo ''boom: config file not found'' >&2; exit 3\\"]\\n\\nEOF\\ni=0; while [ $i -lt 90 ]; do if kubectl logs diag-crash -n $NS --previous 2>/dev/null | grep -q ''config file not found''; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]', '["sh", "-c", "( grep -q ''config file not found'' /tmp/prev.log ) && ( kubectl get pod diag-crash -n $NS >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 직전 컨테이너의 오류 메시지가 있다", "cmd": ["sh", "-c", "grep -q ''config file not found'' /tmp/prev.log"]}, {"label": "Pod diag-crash 는 그대로 있다", "cmd": ["sh", "-c", "kubectl get pod diag-crash -n $NS >/dev/null 2>&1"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 5, 'Last State 의 종료 코드 읽기', 'Pod `diag-exit` 가 계속 재시작합니다. 마지막으로 종료됐을 때의 **종료 코드(Exit Code) 숫자만** `/tmp/exitcode.txt` 에 저장하세요. 직접 보고 옮겨 적어도 되고 `jsonpath` 로 뽑아도 됩니다.', '`kubectl describe pod 이름` 의 Containers 아래 Last State 에 Exit Code 가 있어요. 숫자만 뽑으려면 `-o jsonpath` 로 `lastState.terminated.exitCode` 를 가리키면 돼요.', 'kubectl describe pod diag-exit -n $NS | grep -A6 ''Last State''
kubectl get pod diag-exit -n $NS -o jsonpath=''{.status.containerStatuses[0].lastState.terminated.exitCode}'' > /tmp/exitcode.txt
cat /tmp/exitcode.txt

# 종료 코드 0 은 정상, 0 이 아니면 실패다. 이 Pod 는 42 로 끝난다
# 이 숫자는 프로그램이 정한 값이라 원인은 logs 와 함께 봐야 한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-exit\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo ''bad flag: --port is required'' >&2; exit 42\\"]\\n\\nEOF\\ni=0; while [ $i -lt 90 ]; do if [ -n \\"$(kubectl get pod diag-exit -n $NS -o jsonpath=''{.status.containerStatuses[0].lastState.terminated.exitCode}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]', '["sh", "-c", "( [ \\"$(tr -d ''[:space:]'' < /tmp/exitcode.txt 2>/dev/null)\\" = \\"42\\" ] ) && ( kubectl get pod diag-exit -n $NS >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 종료 코드 42 만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(tr -d ''[:space:]'' < /tmp/exitcode.txt 2>/dev/null)\\" = \\"42\\" ]"]}, {"label": "Pod diag-exit 는 그대로 있다", "cmd": ["sh", "-c", "kubectl get pod diag-exit -n $NS >/dev/null 2>&1"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 6, '옳은 명령으로 Pod 다시 만들어 CrashLoop 벗어나기', 'Pod `diag-fix` 의 명령이 `exit 1` 로 바로 종료되도록 잘못돼 있습니다. **지우고 같은 이름으로 다시 만드세요.** 이미지는 `busybox:1.36`, 명령은 `sleep 3600` 으로 해서 Ready 가 되고 재시작이 0 이어야 합니다.', 'Pod 의 명령(command)은 실행 중에 못 바꿔요. `kubectl delete pod` 로 지운 뒤 `kubectl run 이름 --image=... -- 명령` 으로 다시 만드세요.', 'kubectl delete pod diag-fix -n $NS --grace-period=1
kubectl run diag-fix --image=busybox:1.36 --labels=etude=lab339 -n $NS -- sleep 3600
kubectl get pod diag-fix -n $NS

# 고친 뒤에는 STATUS 가 Running, READY 가 1/1, RESTARTS 가 0 이다
# command 는 Pod 를 만든 뒤에는 바꿀 수 없어서, 이런 오류는 지우고 다시 만드는 것이 기본이다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-fix\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo starting; exit 1\\"]\\n\\nEOF\\nkubectl get pod diag-fix -n $NS -o jsonpath=''{.metadata.uid}'' > /tmp/uid339; i=0; while [ $i -lt 90 ]; do if [ -n \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.status.containerStatuses[0].lastState.terminated.exitCode}'' 2>/dev/null)\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]', '["sh", "-c", "( [ -n \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" ] && [ -s /tmp/uid339 ] && [ \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" != \\"$(cat /tmp/uid339)\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = true ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( [ \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.status.containerStatuses[0].restartCount}'' 2>/dev/null)\\" = \\"0\\" ] ) && ( [ \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.spec.containers[0].image}'' 2>/dev/null)\\" = \\"busybox:1.36\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "원래 Pod 가 아니라 새로 만든 Pod 이다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" ] && [ -s /tmp/uid339 ] && [ \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" != \\"$(cat /tmp/uid339)\\" ]"]}, {"label": "컨테이너가 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = true ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "재시작 횟수가 0 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.status.containerStatuses[0].restartCount}'' 2>/dev/null)\\" = \\"0\\" ]"]}, {"label": "이미지가 busybox:1.36 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod diag-fix -n $NS -o jsonpath=''{.spec.containers[0].image}'' 2>/dev/null)\\" = \\"busybox:1.36\\" ]"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 7, '종료 코드 137 과 OOMKilled', '컨테이너가 계속 죽어서 `describe` 를 봤더니 Last State 가 `Terminated`, Reason 이 `OOMKilled`, Exit Code 가 `137` 이었습니다. 무슨 뜻일까요?', '137 은 128 에 어떤 신호 번호를 더한 값이에요. Reason 이름도 단서예요.', NULL, NULL, '[]', 'choice', '["컨테이너가 메모리 한도(`limits.memory`)를 넘어, 커널이 강제 종료(SIGKILL)했다", "이미지를 받지 못해 컨테이너를 시작하지 못했다", "readinessProbe 가 실패해서 정상적으로 종료됐다", "명령 안의 오류로 프로그램이 스스로 `exit 1` 로 끝났다"]', 0, 'OOM(Out Of Memory)은 메모리 부족입니다. 컨테이너가 `limits.memory` 보다 많이 쓰면 커널이 SIGKILL(9번)로 즉시 종료시키고, 종료 코드는 128+9=137 로 기록됩니다. 이미지를 못 받으면 컨테이너가 시작조차 안 해서 종료 코드가 없고(ImagePullBackOff), 프로브 실패는 Ready 만 바꾸며 종료가 아닙니다. 스스로 `exit 1` 로 끝나면 코드는 1 이고 Reason 은 Error 입니다.', NULL, NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 8, 'OOMKilled 를 describe 로 확인하기', 'Pod `diag-oom` 도 계속 재시작합니다. 마지막으로 종료된 **이유(Reason) 한 단어만** `/tmp/reason.txt` 에 저장하세요. (describe 의 Last State 아래 Reason 입니다.)', '`kubectl describe pod diag-oom` 에서 Last State 를 찾아보세요. 한 단어만 뽑으려면 `-o jsonpath` 로 `lastState.terminated.reason` 을 가리켜도 돼요.', 'kubectl describe pod diag-oom -n $NS | grep -A6 ''Last State''
kubectl get pod diag-oom -n $NS -o jsonpath=''{.status.containerStatuses[0].lastState.terminated.reason}'' > /tmp/reason.txt
cat /tmp/reason.txt

# Reason: OOMKilled, Exit Code: 137 이 보인다 (메모리 한도를 넘었다)
# Limits 의 memory 값이 작은지 같이 본다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/oom.yaml <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-oom\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"x=$(head -c 20000000 /dev/zero | tr -c x x); sleep 3600\\"]\\n    resources:\\n      limits:\\n        memory: 10Mi\\n\\nEOF\\nkubectl apply -n $NS -f /tmp/oom.yaml >/dev/null; kubectl get pod diag-oom -n $NS -o jsonpath=''{.metadata.uid}'' > /tmp/uid339; i=0; while [ $i -lt 90 ]; do if [ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.status.containerStatuses[0].lastState.terminated.reason}'' 2>/dev/null)\\" = \\"OOMKilled\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]', '["sh", "-c", "( [ \\"$(tr -d ''[:space:]'' < /tmp/reason.txt 2>/dev/null)\\" = \\"OOMKilled\\" ] ) && ( kubectl get pod diag-oom -n $NS >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 OOMKilled 만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(tr -d ''[:space:]'' < /tmp/reason.txt 2>/dev/null)\\" = \\"OOMKilled\\" ]"]}, {"label": "Pod diag-oom 은 그대로 있다", "cmd": ["sh", "-c", "kubectl get pod diag-oom -n $NS >/dev/null 2>&1"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 9, '메모리 한도를 키워 OOMKilled 고치기', 'Pod `diag-oom` 의 메모리 한도가 `10Mi` 로 너무 작습니다. 매니페스트 `/tmp/oom.yaml` 이 준비돼 있어요. 한도를 **`128Mi`** 로 고쳐 Pod 를 다시 만들어, 더 이상 죽지 않고 Ready 가 되게 하세요.', '실행 중인 Pod 의 자원 한도는 바꿀 수 없어요. 파일의 값을 고치고(`sed -i` 나 편집기) 기존 Pod 를 지운 뒤 `kubectl apply -f` 로 다시 만드세요.', 'sed -i ''s/memory: 10Mi/memory: 128Mi/'' /tmp/oom.yaml
kubectl delete -f /tmp/oom.yaml -n $NS --grace-period=1
kubectl apply -f /tmp/oom.yaml -n $NS
kubectl get pod diag-oom -n $NS

# 이제 RESTARTS 가 0 이고 Running 이다
# limits.memory 가 실제 사용량보다 작으면 OOMKilled, 너무 크게 잡으면 노드 자원을 낭비한다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; cat > /tmp/oom.yaml <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-oom\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"x=$(head -c 20000000 /dev/zero | tr -c x x); sleep 3600\\"]\\n    resources:\\n      limits:\\n        memory: 10Mi\\n\\nEOF\\nkubectl apply -n $NS -f /tmp/oom.yaml >/dev/null; kubectl get pod diag-oom -n $NS -o jsonpath=''{.metadata.uid}'' > /tmp/uid339; i=0; while [ $i -lt 90 ]; do if [ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.status.containerStatuses[0].lastState.terminated.reason}'' 2>/dev/null)\\" = \\"OOMKilled\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]', '["sh", "-c", "( [ -n \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" ] && [ -s /tmp/uid339 ] && [ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" != \\"$(cat /tmp/uid339)\\" ] ) && ( [ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"128Mi\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = true ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( [ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.status.containerStatuses[0].restartCount}'' 2>/dev/null)\\" = \\"0\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "원래 Pod 가 아니라 새로 만든 Pod 이다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" ] && [ -s /tmp/uid339 ] && [ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.metadata.uid}'' 2>/dev/null)\\" != \\"$(cat /tmp/uid339)\\" ]"]}, {"label": "메모리 한도가 128Mi 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.spec.containers[0].resources.limits.memory}'' 2>/dev/null)\\" = \\"128Mi\\" ]"]}, {"label": "컨테이너가 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = true ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "재시작 횟수가 0 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod diag-oom -n $NS -o jsonpath=''{.status.containerStatuses[0].restartCount}'' 2>/dev/null)\\" = \\"0\\" ]"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 10, 'readinessProbe 실패로 READY 0/1 인 Pod 를 exec 로 고치기', 'Pod `diag-ready` 는 Running 인데 **READY 가 0/1** 입니다. 컨테이너는 죽지 않았어요. readinessProbe 가 `cat /tmp/ready` 를 실행해 성공해야 Ready 가 됩니다. `describe` 로 이유를 확인하고, **`kubectl exec` 로 컨테이너 안에 `/tmp/ready` 파일을 만들어** Pod 가 Ready 가 되게 하세요. (probe 설정은 지우지 마세요.)', '`kubectl describe pod` 의 Events 에 "Readiness probe failed" 가 보여요. `kubectl exec 이름 -- 명령` 으로 컨테이너 안에서 명령을 실행할 수 있어요.', 'kubectl describe pod diag-ready -n $NS | tail -8
kubectl exec diag-ready -n $NS -- touch /tmp/ready
kubectl get pod diag-ready -n $NS

# 몇 초 뒤 READY 가 1/1 이 된다 (RESTARTS 는 0 그대로)
# readiness 실패는 컨테이너를 죽이지 않고 Service 트래픽만 막는다. liveness 실패와 다르다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-ready\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: main\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"sleep 3600\\"]\\n    readinessProbe:\\n      exec:\\n        command: [\\"cat\\", \\"/tmp/ready\\"]\\n      initialDelaySeconds: 1\\n      periodSeconds: 2\\n\\nEOF\\ni=0; while [ $i -lt 60 ]; do if [ \\"$(kubectl get pod diag-ready -n $NS -o jsonpath=''{.status.phase}'' 2>/dev/null)\\" = \\"Running\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1"]', '["sh", "-c", "( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get pod diag-ready -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = true ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( [ \\"$(kubectl get pod diag-ready -n $NS -o jsonpath=''{.status.containerStatuses[0].restartCount}'' 2>/dev/null)\\" = \\"0\\" ] ) && ( kubectl exec diag-ready -n $NS -- test -f /tmp/ready ) && ( [ -n \\"$(kubectl get pod diag-ready -n $NS -o jsonpath=''{.spec.containers[0].readinessProbe.exec.command}'' 2>/dev/null)\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "컨테이너가 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get pod diag-ready -n $NS -o jsonpath=''{.status.containerStatuses[0].ready}'' 2>/dev/null)\\" = true ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "재시작 없이 Ready 가 됐다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod diag-ready -n $NS -o jsonpath=''{.status.containerStatuses[0].restartCount}'' 2>/dev/null)\\" = \\"0\\" ]"]}, {"label": "컨테이너 안에 /tmp/ready 가 있다", "cmd": ["sh", "-c", "kubectl exec diag-ready -n $NS -- test -f /tmp/ready"]}, {"label": "readinessProbe 설정이 남아 있다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get pod diag-ready -n $NS -o jsonpath=''{.spec.containers[0].readinessProbe.exec.command}'' 2>/dev/null)\\" ]"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 11, 'logs -c 로 컨테이너 둘 중 하나의 로그 읽기', 'Pod `diag-multi` 에는 컨테이너가 두 개(`app`, `sidecar`) 있습니다. **`sidecar` 컨테이너의 로그만** `/tmp/sidecar.log` 에 저장하세요.', '컨테이너가 여러 개면 `kubectl logs 이름` 만으로는 어느 것인지 몰라요. `-c 컨테이너이름` 으로 지정하세요.', 'kubectl logs diag-multi -n $NS -c sidecar > /tmp/sidecar.log
cat /tmp/sidecar.log

# sidecar: cache warmed 한 줄이 나온다
# -c 를 안 쓰면 첫 컨테이너(app)의 로그가 나온다. 컨테이너 목록은 describe 로 본다', '["sh", "-c", "rm -f /tmp/*.txt /tmp/*.yaml /tmp/*.log /tmp/uid339; kubectl delete pods -l etude=lab339 -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl delete pod diag-img diag-exit diag-crash diag-fix diag-oom diag-ready diag-multi -n $NS --ignore-not-found --grace-period=1 --wait=true --timeout=90s >/dev/null 2>&1; kubectl apply -n $NS -f - >/dev/null <<''EOF''\\napiVersion: v1\\nkind: Pod\\nmetadata:\\n  name: diag-multi\\n  labels:\\n    etude: lab339\\nspec:\\n  containers:\\n  - name: app\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo ''app: serving on 8080''; sleep 3600\\"]\\n  - name: sidecar\\n    image: busybox:1.36\\n    command: [\\"sh\\", \\"-c\\", \\"echo ''sidecar: cache warmed''; sleep 3600\\"]\\n\\nEOF\\nkubectl wait --for=condition=Ready pod/diag-multi -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( grep -q ''sidecar: cache warmed'' /tmp/sidecar.log ) && ( ! grep -q ''app: serving'' /tmp/sidecar.log )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "sidecar 의 로그가 저장됐다", "cmd": ["sh", "-c", "grep -q ''sidecar: cache warmed'' /tmp/sidecar.log"]}, {"label": "app 의 로그는 섞이지 않았다", "cmd": ["sh", "-c", "! grep -q ''app: serving'' /tmp/sidecar.log"]}]', '[{"title": "파드 디버깅", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/debug-pods/"}, {"title": "컨테이너 종료 원인 확인", "url": "https://kubernetes.io/docs/tasks/debug/debug-application/determine-reason-pod-failure/"}, {"title": "파드 수명 주기", "url": "https://kubernetes.io/docs/concepts/workloads/pods/pod-lifecycle/"}, {"title": "리니스·레디니스 프로브", "url": "https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/"}, {"title": "컨테이너 자원 관리", "url": "https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 11);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 339, 12, '깨진 Pod 를 진단하는 순서', 'Pod 가 CrashLoopBackOff 입니다. 상태를 보고, 원인을 찾고, 고친 뒤 확인하는 순서로 놓아 보세요.', '먼저 목록으로 증상을 보고, 이벤트·종료 정보를 보고, 로그로 이유를 읽어요. 고친 뒤에는 처음 본 명령으로 확인합니다.', NULL, NULL, '[]', 'order', '["`kubectl logs 이름 --previous` 로 직전 컨테이너가 남긴 로그를 읽는다", "`kubectl get pods` 로 STATUS 와 RESTARTS 를 본다", "다시 `kubectl get pods` 로 Running, READY 1/1, RESTARTS 0 인지 확인한다", "원인에 맞게 명령(또는 이미지·한도)을 고쳐 Pod 를 다시 만든다", "`kubectl describe pod 이름` 으로 Last State 의 Exit Code 와 Events 를 본다"]', NULL, '목록(`get pods`)으로 증상을 확인하고, `describe` 로 종료 코드·이유·이벤트를 보고, `logs --previous` 로 죽기 직전 메시지를 읽어 원인을 좁힙니다. 그다음 원인에 맞게 고쳐서 다시 만들고, 처음 쓴 `get pods` 로 정상(Running, 1/1, RESTARTS 0)인지 확인해요. 원인을 모른 채 고치면 같은 문제가 반복됩니다.', '[1, 4, 0, 3, 2]', NULL, NULL, NULL
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 339 AND order_index = 12);
